(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.28)*18 + Math.sin(x*0.016+t*0.38)*12;
  const w2x = Math.sin((x+w1x)*0.012-t*0.15)*8 + Math.cos((y+w1y)*0.01+t*0.2)*6;
  const w2y = Math.cos((y+w1y)*0.014+t*0.18)*8 + Math.sin((x+w1x)*0.011-t*0.25)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*110, 80+Math.cos(t*0.4)*55, 0.075, 2.1, 0.8],
    [320+Math.cos(t*0.5)*110, 160+Math.sin(t*0.7)*55, 0.095, 1.8, 1.0],
    [240+Math.sin(t*0.3+2)*150, 120+Math.cos(t*0.5+1)*95, 0.058, 2.4, 0.7],
    [120+Math.cos(t*0.8+1)*90, 180+Math.sin(t*0.6+3)*65, 0.11, 1.6, 1.2],
    [360+Math.sin(t*0.4+4)*100, 60+Math.cos(t*0.9+2)*75, 0.068, 2.7, 0.6],
    [240+Math.cos(t*0.35+5)*130, 200+Math.sin(t*0.55)*85, 0.085, 2.0, 0.9],
    [80+Math.sin(t*0.65+3)*70, 40+Math.cos(t*0.45+2)*50, 0.13, 1.4, 1.1],
    [400+Math.cos(t*0.55+1)*85, 200+Math.sin(t*0.75+4)*60, 0.072, 2.5, 0.75]
  ];
  let aS=0, iS=0, cS=0;
  for(const[sX,sY,f,sp,p] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w=Math.sin(d*f-t*sp)*Math.exp(-d*0.003);
    aS+=w; iS+=Math.sin(d*f*0.65+t*sp*0.55+1.7)*Math.exp(-d*0.0025)*p;
    cS+=Math.sin(d*f*1.3-t*sp*0.8+3.0)*Math.exp(-d*0.004)*0.5;
  }
  const act=aS/8, inh=iS/8, cross=cS/8;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.9)+Math.sin(sx*0.028-sy*0.038+t*1.2))/2
    +Math.sin((sx+sy)*0.11+t*2.8)*0.18+Math.sin((sx-sy)*0.095-t*2.2)*0.18
    +Math.sin(sx*0.06+t*1.5)*Math.sin(sy*0.06-t*1.3)*0.12;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*4-t*1.6)+Math.sin(dist*0.035+ang*5-t*1.3))*0.35
    +Math.sin(dist*0.08-ang*2+t*0.7)*0.15;
  const voroX=Math.floor(sx/40), voroY=Math.floor(sy/40);
  let minD=999, secD=999;
  for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){
    const cx2=(voroX+dx)*40+Math.sin((voroX+dx)*1.7+(voroY+dy)*2.3+t*0.4)*15;
    const cy2=(voroY+dy)*40+Math.cos((voroX+dx)*2.1+(voroY+dy)*1.9-t*0.35)*15;
    const d2=Math.sqrt((sx-cx2)**2+(sy-cy2)**2);
    if(d2<minD){secD=minD;minD=d2;}else if(d2<secD)secD=d2;
  }
  const voroEdge=Math.tanh((secD-minD)*0.3)*0.25;
  const lap = Math.sin(sx*0.15+0.5)*Math.sin(sy*0.15+0.5)+Math.sin(sx*0.15-0.5)*Math.sin(sy*0.15-0.5)
    +Math.sin(sx*0.15+0.5)*Math.sin(sy*0.15-0.5)+Math.sin(sx*0.15-0.5)*Math.sin(sy*0.15+0.5)-4*Math.sin(sx*0.15)*Math.sin(sy*0.15);
  const diff=lap*0.15;
  const reaction=Math.tanh((act-inh*0.65+bg*0.28+spiral+cross*0.4+diff)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.095+t)*0.45)*1.4)*0.22;
  const pulse=0.5+0.5*Math.sin(t*0.8+dist*0.02)*Math.exp(-dist*0.005);
  const blend=reaction*0.6+cell*0.15+voroEdge*0.12+pulse*0.06+cross*0.07;
  const v=blend*0.5+0.5;
  const pal=[
    [5,12,52],[10,45,85],[12,85,115],[18,140,135],[45,175,150],
    [140,195,120],[210,195,75],[220,155,60],[215,110,65],[185,65,75],
    [130,35,80],[70,18,60],[30,10,48],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const smooth=f*f*(3-2*f);
  const r0=pal[i][0]+(pal[i+1][0]-pal[i][0])*smooth;
  const g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*smooth;
  const b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*smooth;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.max(0,1.0-Math.abs(reaction)*1.5)*0.15;
  const warmth=0.5+0.5*Math.sin(ang*2+t*0.3);
  return[
    Math.min(255,((r0*(1+glow*0.6)+glow*40)*lum*edge+warmth*8)|0),
    Math.min(255,((g0*(1+glow*0.4)+glow*30)*lum*edge)|0),
    Math.min(255,((b0*(1+glow*0.8)+glow*50)*(lum-edge*0.03)+warmth*(-5))|0)
  ];
}
